def decimal_to_binary(decimal):
    def convert_integer_to_binary(integer_part):
        if integer_part == 0:
            return '0'
        binary = ''
        while integer_part > 0:
            binary = str(integer_part % 2) + binary
            integer_part //= 2
        return binary

    def convert_fractional_to_binary(fractional_part):
        if fractional_part == 0:
            return ''
        binary = ''
        while fractional_part != 1:
            fractional_part *= 2
            if fractional_part >= 1:
                binary += '1'
                fractional_part -= 1
            else:
                binary += '0'
        return binary

    integer_part = int(decimal)
    fractional_part = decimal - integer_part

    binary_integer = convert_integer_to_binary(integer_part)
    binary_fractional = convert_fractional_to_binary(fractional_part)

    binary_representation = 'db' + binary_integer + '.' + binary_fractional + 'db'
    return binary_representation

# Test cases
print(decimal_to_binary(15))   # returns "db1111db"
print(decimal_to_binary(32))   # returns "db100000db"

